#[derive(Clone,Copy)]struct BNode{var:u32,lo:u32,hi:u32}
struct Bdd{nodes:Vec<BNode>,unique:std::collections::HashMap<(u32,u32,u32),u32>,memo:std::collections::HashMap<(bool,u32,u32),u32>}
impl Bdd{
 fn new()->Self{Self{nodes:vec![BNode{var:u32::MAX,lo:0,hi:0},BNode{var:u32::MAX,lo:1,hi:1}],unique:std::collections::HashMap::new(),memo:std::collections::HashMap::new()}}
 fn node(&mut self,var:u32,lo:u32,hi:u32)->u32{if lo==hi{return lo;}if let Some(id)=self.unique.get(&(var,lo,hi)){return *id;}assert!(self.nodes.len()<2_000_000,"BDD resource UNKNOWN; never a proof");let id=self.nodes.len()as u32;self.nodes.push(BNode{var,lo,hi});self.unique.insert((var,lo,hi),id);id}
 fn apply(&mut self,and:bool,x:u32,y:u32)->u32{let(x,y)=(x.min(y),x.max(y));if and{if x==0{return 0;}if x==1{return y;}if x==y{return x;}}else{if x==0{return y;}if x==y{return 0;}}if let Some(id)=self.memo.get(&(and,x,y)){return *id;}if x<=1&&y<=1{return if and{x&y}else{x^y};}let xn=self.nodes[x as usize];let yn=self.nodes[y as usize];let var=xn.var.min(yn.var);let(xl,xh)=if xn.var==var{(xn.lo,xn.hi)}else{(x,x)};let(yl,yh)=if yn.var==var{(yn.lo,yn.hi)}else{(y,y)};let lo=self.apply(and,xl,yl);let hi=self.apply(and,xh,yh);let id=self.node(var,lo,hi);self.memo.insert((and,x,y),id);id}
 fn coefficients(d:&Dag,order:&std::collections::BTreeMap<u32,u32>)->(Self,Vec<u32>){let mut b=Self::new();let mut v=vec![0;d.nodes.len()];v[1]=1;for(i,n)in d.nodes.iter().enumerate().skip(2){assert!(!n.random,"input coefficient must never contain MR");v[i]=match n.kind{2=>b.node(order.get(&(i as u32)).copied().unwrap_or(10000+i as u32),0,1),3=>b.apply(false,v[n.a as usize],v[n.b as usize]),4=>b.apply(true,v[n.a as usize],v[n.b as usize]),7=>{let mut out=0;for term in d.large_defs[n.a as usize].iter(){let mut p=1;for id in d.monomials[*term as usize].iter(){assert!((*id as usize)<i);p=b.apply(true,p,v[*id as usize]);}out=b.apply(false,out,p);}out},8=>{let mut out=1;for term in[n.a,n.b]{for id in d.monomials[term as usize].iter(){assert!((*id as usize)<i);out=b.apply(true,out,v[*id as usize]);}}out},_=>panic!("unsupported exact coefficient definition")};}for i in 0..v.len(){assert_eq!(v[i],v[d.find(i as u32)as usize],"independent BDD disagrees with input-DAG equality");}(b,v)}
}
#[cfg(test)]mod bdd_tests{use super::*;
 fn eval(b:&Bdd,mut id:u32,bits:u32)->bool{while id>1{let n=b.nodes[id as usize];id=if bits>>n.var&1==0{n.lo}else{n.hi};}id==1}
 #[test]fn boolean_laws_and_variable_order(){let mut b=Bdd::new();let x=b.node(0,0,1);let y=b.node(1,0,1);let xy=b.apply(true,x,y);let nx=b.apply(false,x,1);let impossible=b.apply(true,xy,nx);assert_eq!(impossible,0);let z=b.apply(false,xy,x);for bits in 0..4{assert_eq!(eval(&b,z,bits),(bits&1!=0)^(bits&3==3));}}
 #[test]fn independently_replays_all_coefficient_definitions(){let mut d=Dag::new();let xs:Vec<_>=(0..6).map(|_|d.variable(false)).collect();let mut ids=xs.clone();let mut state=819173u64;let mut ops=Vec::new();for i in 0..1000{state=state.wrapping_mul(6364136223846793005).wrapping_add(1);let x=ids[state as usize%ids.len()];state=state.rotate_left(19);let y=ids[state as usize%ids.len()];let and=i%3==0;let z=if and{d.and(x,y)}else{d.xor(x,y)};ids.push(z);ops.push((and,x,y,z));}let order=xs.iter().enumerate().map(|(i,id)|(*id,i as u32)).collect();let(b,v)=Bdd::coefficients(&d,&order);for bits in 0..64{for(and,x,y,z)in &ops{assert_eq!(eval(&b,v[*z as usize],bits),if *and{eval(&b,v[*x as usize],bits)&eval(&b,v[*y as usize],bits)}else{eval(&b,v[*x as usize],bits)^eval(&b,v[*y as usize],bits)});}}}
}
